-- URMA · step 8, part 2 of 2 · Trial data: ticks from the scanned folders and the matrix back-fill
-- Run AFTER part 1. Safe to run again.
begin;

-- ===== 4. Ticks read from the scanned paper folders =====
create temp table _scan (name text, code text, tick text, line_nos int[], pages text, who text) on commit drop;

select i.id, l.id, s.tick, case when s.tick = 'self' then null else coalesce(nullif(s.who,''), 'Paper folder') end, 'scan',
       'Read from the scanned paper folder (' || s.pages || ')' || case when s.who <> '' then ' · initials in the box: ' || s.who else '' end
from _scan s
join instructors i on lower(i.name) = lower(s.name)
join competencies c on c.code = s.code
join competency_lines l on l.comp_id = c.id and l.sort_order = any (s.line_nos)
on conflict (instructor_id, line_id, tick_type) do nothing;

-- ===== 5. Back-fill from the matrix =====
-- Competent = every box ticked. Indirect = every Self and Observation box ticked. Direct or blank = nothing added.
create temp table _matrix (name text, code text, status text, site text) on commit drop;

select i.id, l.id, t.tick, m.site, case when t.tick = 'self' then null else 'Matrix back-fill' end, 'backfill',
       'Back-filled from the competency matrix (' || m.status || '), November 2026'
from _matrix m
join instructors i on lower(i.name) = lower(m.name)
join competencies c on c.code = m.code
join competency_lines l on l.comp_id = c.id
cross join lateral (values ('self', l.needs_self), ('obs1', l.needs_obs1), ('obs2', l.needs_obs2),
                           ('assess1', l.needs_assess1), ('assess2', l.needs_assess2), ('assess3', l.needs_assess3)) as t(tick, needed)
where t.needed and (m.status = 'Competent' or t.tick in ('self','obs1','obs2'))
on conflict (instructor_id, line_id, tick_type) do nothing;

values ('Data import', 'Sign-off', 'Trial data loaded: competencies from 2024 templates, ticks from scanned folders and matrix back-fill', 'Initial data load, November 2026');
commit;
